mkdir -p /app/output && cat > /app/output/index.html <<'HTML'
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>CreativeHub — Online Classes for Creatives</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=Inter:wght@400;500;600&display=swap" rel="stylesheet">
  <style>
    :root {
      --bg-dark: #10131d;
      --bg-dark-2: #171b29;
      --text: #121316;
      --text-soft: #5b6272;
      --surface: #ffffff;
      --surface-alt: #f4f6fb;
      --green: #55da9b;
      --purple: #5620c1;
      --coral: #ff6b57;
      --yellow: #ffd45b;
      --radius: 18px;
      --shadow: 0 12px 28px rgba(16, 19, 29, 0.12);
      --container: min(1160px, 92vw);
    }

    * { box-sizing: border-box; }
    html, body { margin: 0; padding: 0; }
    body {
      font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
      color: var(--text);
      background: #ffffff;
      line-height: 1.45;
    }
    h1, h2, h3, h4 {
      font-family: "Plus Jakarta Sans", Inter, sans-serif;
      line-height: 1.12;
      margin: 0;
      letter-spacing: -0.02em;
    }
    p { margin: 0; color: var(--text-soft); }
    a { color: inherit; text-decoration: none; }

    .container { width: var(--container); margin: 0 auto; }
    .section { padding: 4.5rem 0; }

    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: .55rem;
      border: 0;
      border-radius: 999px;
      font-weight: 700;
      font-family: "Plus Jakarta Sans", sans-serif;
      font-size: .96rem;
      cursor: pointer;
      transition: transform .22s ease, box-shadow .22s ease, background .22s ease;
      padding: .88rem 1.25rem;
    }
    .btn:hover { transform: translateY(-1px); }
    .btn:focus-visible { outline: 2px solid #fff; outline-offset: 2px; }
    .btn-primary {
      background: linear-gradient(135deg, var(--coral), #ff7f57);
      color: #fff;
      box-shadow: 0 10px 22px rgba(255, 107, 87, .3);
    }
    .btn-secondary {
      background: #fff;
      color: #141726;
      box-shadow: 0 8px 20px rgba(0,0,0,.17);
    }
    .btn-dark {
      background: #171b29;
      color: #fff;
    }

    header {
      position: sticky;
      top: 0;
      z-index: 20;
      backdrop-filter: saturate(180%) blur(10px);
      background: rgba(255,255,255,.83);
      border-bottom: 1px solid #eceff5;
    }
    .nav {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 76px;
      gap: 1rem;
    }
    .brand {
      display: inline-flex;
      align-items: center;
      gap: .65rem;
      font-family: "Plus Jakarta Sans", sans-serif;
      font-weight: 800;
      font-size: 1.2rem;
      letter-spacing: -.02em;
    }
    .brand-dot {
      width: 28px;
      height: 28px;
      border-radius: 9px;
      background: conic-gradient(from 120deg, var(--green), var(--purple), var(--coral), var(--green));
      box-shadow: 0 6px 14px rgba(86,32,193,.25);
    }
    .nav-links {
      display: flex;
      align-items: center;
      gap: 1.25rem;
      color: #3f4558;
      font-weight: 500;
    }

    .hero-wrap {
      background: radial-gradient(circle at 15% 10%, rgba(85,218,155,.2), transparent 35%),
                  radial-gradient(circle at 85% 80%, rgba(255,212,91,.17), transparent 30%),
                  linear-gradient(145deg, var(--bg-dark), var(--bg-dark-2));
      color: #fff;
      padding: 2.6rem 0 3.6rem;
    }
    .hero {
      display: grid;
      grid-template-columns: 1.04fr .96fr;
      gap: 2rem;
      align-items: center;
    }
    .eyebrow {
      display: inline-flex;
      padding: .4rem .7rem;
      border-radius: 999px;
      background: rgba(255,255,255,.09);
      border: 1px solid rgba(255,255,255,.2);
      font-size: .78rem;
      font-weight: 600;
      margin-bottom: 1rem;
    }
    .hero h1 {
      font-size: clamp(2rem, 4.8vw, 3.35rem);
      max-width: 16ch;
      margin-bottom: .9rem;
    }
    .hero-sub {
      color: #d9deee;
      font-size: 1.05rem;
      margin-bottom: 1.5rem;
    }
    .hero-cta {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: .72rem;
      max-width: 520px;
    }
    .legal {
      margin-top: .9rem;
      color: #b7bfd3;
      font-size: .78rem;
      max-width: 58ch;
    }

    .hero-art {
      background: linear-gradient(145deg, rgba(255,255,255,.06), rgba(255,255,255,.02));
      border: 1px solid rgba(255,255,255,.12);
      border-radius: 24px;
      padding: 1.1rem;
      box-shadow: 0 14px 34px rgba(0,0,0,.33);
    }
    .mosaic {
      display: grid;
      grid-template-columns: 1.15fr .85fr;
      gap: .75rem;
    }
    .tile {
      border-radius: 16px;
      min-height: 108px;
      padding: .9rem;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      color: #fff;
      font-family: "Plus Jakarta Sans", sans-serif;
      font-weight: 600;
    }
    .tile-lg { min-height: 228px; background: linear-gradient(150deg, #673abf, #3e1f88); }
    .tile-a { background: linear-gradient(150deg, #2f8e66, #25634b); }
    .tile-b { background: linear-gradient(150deg, #c74b39, #842f24); }
    .tile small { font-family: Inter, sans-serif; opacity: .9; }

    .pills {
      margin-top: 1.35rem;
      display: flex;
      gap: .65rem;
      overflow-x: auto;
      scrollbar-width: thin;
      padding-bottom: .25rem;
    }
    .pill {
      flex: 0 0 auto;
      border: 1px solid rgba(255,255,255,.22);
      background: rgba(255,255,255,.07);
      color: #f4f7ff;
      border-radius: 999px;
      padding: .52rem .9rem;
      font-weight: 600;
      font-size: .85rem;
    }

    .section-title { font-size: clamp(1.6rem, 3vw, 2.2rem); margin-bottom: .75rem; }
    .section-sub { max-width: 65ch; margin-bottom: 1.5rem; }

    .feature-grid, .testimonials, .footer-grid {
      display: grid;
      gap: 1rem;
    }
    .feature-grid { grid-template-columns: repeat(4, 1fr); }
    .feature-card {
      background: var(--surface-alt);
      border-radius: var(--radius);
      padding: 1.15rem;
      border: 1px solid #e7ebf4;
    }

    .stats-band {
      background: #0e1119;
      color: #fff;
      border-radius: 24px;
      padding: 2rem 1.4rem;
    }
    .stats {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 1rem;
      text-align: center;
    }
    .stat-num {
      font-size: clamp(1.8rem, 4vw, 2.7rem);
      font-family: "Plus Jakarta Sans", sans-serif;
      font-weight: 800;
      color: var(--yellow);
    }
    .stat-label { color: #c9d0e3; font-weight: 500; }

    .tabs {
      display: flex;
      gap: .58rem;
      overflow-x: auto;
      padding-bottom: .35rem;
      margin-bottom: 1rem;
    }
    .tab {
      border: 1px solid #e2e7f1;
      border-radius: 999px;
      background: #fff;
      color: #2e3445;
      font-weight: 600;
      padding: .48rem .86rem;
      cursor: pointer;
      white-space: nowrap;
    }
    .tab.active {
      background: #171b29;
      color: #fff;
      border-color: #171b29;
    }

    .course-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 1rem;
    }
    .course-card {
      border: 1px solid #e8edf7;
      border-radius: 18px;
      overflow: hidden;
      background: #fff;
      box-shadow: 0 6px 18px rgba(12,17,33,.06);
      transition: transform .2s ease, box-shadow .2s ease;
    }
    .course-card:hover { transform: translateY(-4px); box-shadow: var(--shadow); }
    .thumb {
      height: 145px;
      position: relative;
      background: #ddd;
      display: flex;
      align-items: end;
      padding: .7rem;
      color: #fff;
      font-weight: 700;
      font-family: "Plus Jakarta Sans", sans-serif;
    }
    .course-body { padding: .86rem .9rem 1rem; }
    .course-title {
      font-family: "Plus Jakarta Sans", sans-serif;
      font-size: .95rem;
      margin-bottom: .48rem;
      display: -webkit-box;
      -webkit-line-clamp: 2;
      -webkit-box-orient: vertical;
      overflow: hidden;
      min-height: 2.5em;
    }
    .meta { color: #616a7d; font-size: .83rem; display: flex; gap: .52rem; flex-wrap: wrap; }

    .feed-cols { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1rem; }

    .teacher-head {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 1rem;
      margin-bottom: .95rem;
    }
    .carousel-wrap { position: relative; }
    .teacher-row {
      display: flex;
      gap: .95rem;
      overflow-x: auto;
      scroll-behavior: smooth;
      padding-bottom: .45rem;
      scrollbar-width: thin;
    }
    .teacher-card {
      flex: 0 0 clamp(215px, 27vw, 280px);
      border: 1px solid #e8edf7;
      background: #fff;
      border-radius: 18px;
      padding: .95rem;
    }
    .avatar {
      width: 100%;
      aspect-ratio: 16/11;
      border-radius: 14px;
      margin-bottom: .75rem;
      background: linear-gradient(120deg, #5d2ac8, #2c9272);
      position: relative;
      overflow: hidden;
    }
    .avatar::after {
      content: "";
      position: absolute;
      inset: 0;
      background: radial-gradient(circle at 70% 25%, rgba(255,255,255,.3), transparent 40%);
    }

    .carousel-btns { display: inline-flex; gap: .5rem; }
    .icon-btn {
      width: 38px;
      height: 38px;
      border-radius: 999px;
      border: 1px solid #dce3f1;
      background: #fff;
      cursor: pointer;
    }

    .testimonials { grid-template-columns: repeat(2, 1fr); }
    .quote {
      border: 1px solid #e7ebf5;
      border-radius: 18px;
      padding: 1rem;
      background: #fff;
    }

    .teams {
      border-radius: 24px;
      padding: 2rem;
      background: linear-gradient(130deg, #f7f9ff, #f2fff8);
      border: 1px solid #e4ecf2;
      display: grid;
      grid-template-columns: 1.15fr .85fr;
      gap: 1rem;
      align-items: center;
    }

    .faq {
      border-top: 1px solid #e8edf6;
    }
    .faq-item {
      border-bottom: 1px solid #e8edf6;
    }
    .faq-q {
      width: 100%;
      background: #fff;
      border: 0;
      text-align: left;
      padding: 1rem 0;
      font-family: "Plus Jakarta Sans", sans-serif;
      font-size: 1rem;
      display: flex;
      justify-content: space-between;
      align-items: center;
      cursor: pointer;
    }
    .faq-a {
      max-height: 0;
      overflow: hidden;
      transition: max-height .24s ease;
      color: #5d6679;
      padding-right: 1.2rem;
    }
    .faq-item.active .faq-a { max-height: 220px; padding-bottom: .95rem; }

    footer {
      margin-top: 3rem;
      padding: 2.5rem 0;
      border-top: 1px solid #e8edf6;
      background: #fafbff;
    }
    .footer-grid { grid-template-columns: 1.2fr 1fr 1fr 1fr; }
    .footer-title {
      font-family: "Plus Jakarta Sans", sans-serif;
      font-weight: 700;
      margin-bottom: .6rem;
    }
    .footer-list { display: grid; gap: .4rem; color: #5f677b; font-size: .92rem; }

    .modal {
      position: fixed;
      inset: 0;
      background: rgba(8,10,16,.55);
      display: none;
      align-items: center;
      justify-content: center;
      z-index: 40;
      padding: 1rem;
    }
    .modal.open { display: flex; }
    .modal-card {
      width: min(460px, 92vw);
      background: #fff;
      border-radius: 18px;
      padding: 1.2rem;
    }

    @media (max-width: 1024px) {
      .hero { grid-template-columns: 1fr; }
      .feature-grid { grid-template-columns: repeat(2, 1fr); }
      .course-grid { grid-template-columns: repeat(2, 1fr); }
      .feed-cols { grid-template-columns: 1fr; }
      .teams { grid-template-columns: 1fr; }
      .footer-grid { grid-template-columns: repeat(2, 1fr); }
    }
    @media (max-width: 640px) {
      .nav-links .hide-sm { display: none; }
      .hero-cta { grid-template-columns: 1fr; }
      .feature-grid, .course-grid, .stats, .testimonials, .footer-grid { grid-template-columns: 1fr; }
      .section { padding: 3.4rem 0; }
    }
  </style>
</head>
