  <script>
    const tabNames = [
      'Featured','Music','Drawing & Painting','Marketing','Animation','Social Media','UI/UX Design','Creative Writing','Digital Illustration','Film & Video','Crafts','Freelance & Entrepreneurship','Graphic Design','Photography','Productivity'
    ];

    const courses = [
      {title:'Kickstart your Creativity with Procreate: 20 Fun Drawings for Beginners and Beyond',instructor:'Lisa Bardot',students:'24,872',duration:'6h 24m',categories:['Featured','Drawing & Painting','Digital Illustration']},
      {title:'Social Media Content Creation in Canva: From Beginner to Advanced',instructor:'Maggie Stara',students:'44,495',duration:'13h 19m',categories:['Featured','Social Media','Marketing','Graphic Design']},
      {title:'Landscapes: A Free-Flow Watercolour Masterclass',instructor:'Jane Davies',students:'2,579',duration:'1h 42m',categories:['Featured','Drawing & Painting']},
      {title:'Figma UI UX Design Advanced: Become a Pro',instructor:'Daniel Scott',students:'6,692',duration:'8h 48m',categories:['Featured','UI/UX Design']},
      {title:'ChatGPT for Creatives: AI-Powered SEO, Marketing, & Productivity',instructor:'Peggy Dean',students:'18,842',duration:'1h 18m',categories:['Featured','Marketing','Productivity','Freelance & Entrepreneurship']},
      {title:"How to Draw: A Beginner's Guide",instructor:'Brent Eviston',students:'26,243',duration:'5h 57m',categories:['Featured','Drawing & Painting']},
      {title:'Learn Video Editing With Premiere Pro For Beginners',instructor:'Jordy Vandeput',students:'17,887',duration:'3h 44m',categories:['Featured','Film & Video']},
      {title:'iPhone Photography Essentials: Take Pro Photos With Your iPhone',instructor:'Sean Dalton',students:'13,423',duration:'1h 34m',categories:['Featured','Photography']}
    ];

    const thumbStyles = [
      'linear-gradient(120deg,#3c4ad8,#5ad0a1)',
      'linear-gradient(120deg,#ff6b57,#ff9d5c)',
      'linear-gradient(120deg,#3e5dcc,#5620c1)',
      'linear-gradient(120deg,#1d2738,#4370ff)',
      'linear-gradient(120deg,#1d8f69,#55da9b)',
      'linear-gradient(120deg,#4b2d88,#b65ce5)',
      'linear-gradient(120deg,#2a3248,#5f6f8f)',
      'linear-gradient(120deg,#1d7cc2,#39c1d6)'
    ];

    const tabsEl = document.getElementById('courseTabs');
    const gridEl = document.getElementById('courseGrid');
    let activeTab = 'Featured';

    function renderTabs() {
      tabsEl.innerHTML = '';
      tabNames.forEach(name => {
        const btn = document.createElement('button');
        btn.className = `tab ${name === activeTab ? 'active' : ''}`;
        btn.textContent = name;
        btn.addEventListener('click', () => {
          activeTab = name;
          renderTabs();
          renderCourses();
        });
        tabsEl.appendChild(btn);
      });
    }

    function renderCourses() {
      const visible = activeTab === 'Featured' ? courses : courses.filter(c => c.categories.includes(activeTab));
      gridEl.innerHTML = '';
      (visible.length ? visible : courses.slice(0,4)).forEach((course, i) => {
        const card = document.createElement('article');
        card.className = 'course-card';
        card.innerHTML = `
          <div class="thumb" style="background:${thumbStyles[i % thumbStyles.length]};">
            <span>${course.duration}</span>
          </div>
          <div class="course-body">
            <div class="course-title">${course.title}</div>
            <div class="meta"><span>${course.instructor}</span><span>• ${course.students} students</span><span>• ${course.duration}</span></div>
          </div>
        `;
        gridEl.appendChild(card);
      });
    }

    renderTabs();
    renderCourses();

    const faq = document.getElementById('faq');
    faq.querySelectorAll('.faq-q').forEach(btn => {
      btn.addEventListener('click', () => {
        const item = btn.closest('.faq-item');
        const isActive = item.classList.contains('active');
        faq.querySelectorAll('.faq-item').forEach(el => el.classList.remove('active'));
        if (!isActive) item.classList.add('active');
      });
    });

    const teacherRow = document.getElementById('teacherRow');
    document.getElementById('prevTeachers').addEventListener('click', () => teacherRow.scrollBy({ left: -300, behavior: 'smooth' }));
    document.getElementById('nextTeachers').addEventListener('click', () => teacherRow.scrollBy({ left: 300, behavior: 'smooth' }));

    const modal = document.getElementById('signupModal');
    const modalTitle = document.getElementById('modalTitle');
    document.getElementById('googleSignup').addEventListener('click', () => {
      modalTitle.textContent = 'Continue with Google';
      modal.classList.add('open');
    });
    document.getElementById('emailSignup').addEventListener('click', () => {
      modalTitle.textContent = 'Continue with email';
      modal.classList.add('open');
    });
    document.getElementById('closeModal').addEventListener('click', () => modal.classList.remove('open'));
    modal.addEventListener('click', (e) => {
      if (e.target === modal) modal.classList.remove('open');
    });
  </script>
